1	// Loads the built site in headless Chromium. Exits non-zero if a page renders blank, scrolls
2	// sideways, or shows an inner horizontal scrollbar on step output.
3	// Usage: node web/check-render.mjs [baseUrl] [runId] [screenshotDir]
4	// Needs the API (which also serves web/dist) already running and `chromium` on PATH.
5	import { spawn, spawnSync } from "node:child_process";
6	import { mkdirSync, writeFileSync } from "node:fs";
7	import { tmpdir } from "node:os";
8	import { join } from "node:path";
9	
10	const base = process.argv[2] ?? "http://REDACTED:8787";
11	const runId = process.argv[3] ?? "20261010T101804Z-5c3370f";
12	const outDir = process.argv[4] ?? join(tmpdir(), "resurgo-shots");
13	mkdirSync(outDir, { recursive: true });
14	
15	const pages = [["landing", "/"], ["runs", "/runs"], ["run", `/runs/${runId}`]];
16	const INSTALL_URL = "https://github.com/apps/resurgo-agent/installations/new";
17	const widths = [420, 1280];
18	const themes = ["light", "dark"];
19	const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
20	
21	/** Text inside #root: everything after its opening tag, minus scripts and markup. */
22	function rootText(dom) {
23	  const at = dom.search(/<div id="root"[^>]*>/);
24	  if (at < 0) return "";
25	  return dom
26	    .slice(at)
27	    .replace(/<(script|style)[\s\S]*?<\/\1>/g, "")
28	    .replace(/<[^>]+>/g, " ")
29	    .replace(/\s+/g, " ")
30	    .trim();
31	}
32	
33	// Runs in the page. Step output is the run view's scroller and every <pre> in a terminal list.
34	const PROBE = `(() => {
35	  const vw = document.documentElement.clientWidth;
36	  const name = (e) => e.tagName.toLowerCase() + '.' + String(e.getAttribute('class') || '').split(/\\s+/).slice(0, 5).join('.');
37	  const over = [...document.querySelectorAll('body *')]
38	    .filter((e) => { const r = e.getBoundingClientRect(); return r.width && r.right > vw + 1; })
39	    .map((e) => name(e) + ' right=' + Math.round(e.getBoundingClientRect().right))
40	    .slice(0, 8);
41	  const stepOut = '[aria-label^="Terminal output"], [aria-label^="Terminal output"] *, ol[role="list"] pre';
42	  const inner = [...document.querySelectorAll('body *')]
43	    .filter((e) => { const s = getComputedStyle(e); return (s.overflowX === 'auto' || s.overflowX === 'scroll') && e.scrollWidth > e.clientWidth + 1; })
44	    .map((e) => ({ el: name(e), step: e.matches(stepOut) }));
45	  const install = [...document.querySelectorAll('a')].filter((a) => /Install on GitHub/i.test(a.textContent || '')).map((a) => a.href);
46	  return JSON.stringify({ vw, scrollWidth: document.documentElement.scrollWidth, over, inner, install });
47	})()`;
48	
49	/** One headless Chromium with a CDP socket, for viewport width, colour scheme and measurements. */
50	async function openBrowser() {
51	  const port = 9300 + Math.floor(Math.random() * 600);
52	  const proc = spawn(
53	    "chromium",
54	    ["--headless=new", "--disable-gpu", "--no-sandbox", `--remote-debugging-port=${port}`, `--user-data-dir=${join(outDir, ".profile")}`, "about:blank"],
55	    { stdio: "ignore" },
56	  );
57	  let tab;
58	  for (let i = 0; i < 50 && !tab; i++) {
59	    try {
60	      tab = (await (await fetch(`http://REDACTED:${port}/json`)).json()).find((t) => t.type === "page");
61	    } catch {}
62	    if (!tab) await sleep(200);
63	  }
64	  if (!tab) throw new Error("chromium did not start");
65	  const ws = new WebSocket(tab.webSocketDebuggerUrl);
66	  await new Promise((r) => (ws.onopen = r));
67	  let n = 0;
68	  const waiting = new Map();
69	  ws.onmessage = (m) => {
70	    const d = JSON.parse(m.data);
71	    waiting.get(d.id)?.(d);
72	  };
73	  const send = (method, params = {}) =>
74	    new Promise((res) => {
75	      waiting.set(++n, res);
76	      ws.send(JSON.stringify({ id: n, method, params }));
77	    });
78	  const value = async (expression) => (await send("Runtime.evaluate", { expression, returnByValue: true })).result.result.value;
79	  return { send, value, close: () => { ws.close(); proc.kill(); } };
80	}
81	
82	let failed = false;
83	for (const [name, path] of pages) {
84	  const r = spawnSync("chromium", ["--headless=new", "--disable-gpu", "--no-sandbox", "--virtual-time-budget=6000", "--dump-dom", base + path], {
85	    encoding: "utf8",
86	    maxBuffer: 64 * 1024 * 1024,
87	  });
88	  const text = rootText(r.stdout ?? "");
89	  const broken = /could not be shown/.test(text);
90	  const ok = r.status === 0 && text.length >= 80 && !broken;
91	  failed ||= !ok;
92	  console.log(`${ok ? "PASS" : "FAIL"} ${path}  root text: ${text.length} chars${broken ? ", a section failed to render" : ""}`);
93	  if (!ok && r.stderr) console.log(r.stderr.split("\n").slice(-5).join("\n"));
94	}
95	
96	const browser = await openBrowser();
97	for (const [name, path] of pages) {
98	  for (const width of widths) {
99	    for (const theme of themes) {
100	      await browser.send("Emulation.setDeviceMetricsOverride", { width, height: 900, deviceScaleFactor: 1, mobile: false });
101	      await browser.send("Emulation.setEmulatedMedia", { features: [{ name: "prefers-color-scheme", value: theme }] });
102	      await browser.send("Page.navigate", { url: base + path });
103	      await sleep(5500);
104	      // Measure at the first screen, before anything below the fold has revealed.
