// Serves web/dist, proxies /api and /index.md to the running API, and (DEMO=1) adds one synthetic
// "fix verified, awaiting approval" run derived from a real one. Scratch tool, not part of the repo.
import { createServer } from "node:http";
import { readFile } from "node:fs/promises";
import { extname, join, normalize } from "node:path";

const UP = "http://REDACTED:8787";
const DIST = "/home/timidan/Desktop/resurgo-web/web/dist";
const port = Number(process.argv[2] ?? 8790);
const demo = process.env.DEMO === "1";
const FAKE = "20261010T140000Z-5c3370f";
const SRC = "20261010T101804Z-5c3370f";
const types = { ".html": "text/html", ".js": "text/javascript", ".css": "text/css", ".svg": "image/svg+xml", ".png": "image/png", ".webp": "image/webp", ".woff2": "font/woff2", ".woff": "font/woff", ".json": "application/json", ".md": "text/markdown" };

const awaiting = (s) => ({ ...s, id: FAKE, status: "fix_awaiting_approval", needs_approval: true, verified: true, fix_kind: "code", started: s.started + 3600 });

createServer(async (req, res) => {
  const url = new URL(req.url, "http://x");
  try {
    if (url.pathname === "/api/runs" && demo) {
      const list = await (await fetch(UP + "/api/runs")).json();
      const src = list.find((r) => r.id === SRC);
      res.setHeader("content-type", "application/json");
      return res.end(JSON.stringify(src ? [awaiting(src), ...list] : list));
    }
    if (url.pathname === `/api/runs/${FAKE}` && demo) {
      const d = await (await fetch(`${UP}/api/runs/${SRC}`)).json();
      d.summary = awaiting(d.summary);
      d.result = { ...d.result, run_id: FAKE, needs_approval: true, result: "runs" };
      res.setHeader("content-type", "application/json");
      return res.end(JSON.stringify(d));
    }
    if (url.pathname.startsWith("/api/") || url.pathname === "/index.md" || url.pathname === "/llms.txt") {
      const r = await fetch(UP + url.pathname + url.search);
      res.statusCode = r.status;
      res.setHeader("content-type", r.headers.get("content-type") ?? "text/plain");
      return res.end(Buffer.from(await r.arrayBuffer()));
    }
    let file = normalize(join(DIST, url.pathname));
    if (!file.startsWith(DIST)) file = join(DIST, "index.html");
    let body;
    try {
      body = await readFile(file);
    } catch {
      file = join(DIST, "index.html");
      body = await readFile(file);
    }
    res.setHeader("content-type", types[extname(file)] ?? "application/octet-stream");
    res.end(body);
  } catch (e) {
    res.statusCode = 500;
    res.end(String(e));
  }
}).listen(port, "REDACTED", () => console.log("mock on", port, demo ? "(demo)" : ""));

