import { spawn } from "node:child_process";
import { mkdirSync, writeFileSync } from "node:fs";
import { join } from "node:path";

const base = process.argv[2];
const out = process.argv[3];
mkdirSync(out, { recursive: true });
const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
const port = 9900 + Math.floor(Math.random() * 90);
const proc = spawn("chromium", ["--headless=new", "--disable-gpu", "--no-sandbox", `--remote-debugging-port=${port}`, `--user-data-dir=${join(out, ".profile")}`, "about:blank"], { stdio: "ignore" });
let tab;
for (let i = 0; i < 50 && !tab; i++) {
  try { tab = (await (await fetch(`http://REDACTED:${port}/json`)).json()).find((t) => t.type === "page"); } catch {}
  if (!tab) await sleep(200);
}
const ws = new WebSocket(tab.webSocketDebuggerUrl);
await new Promise((r) => (ws.onopen = r));
let n = 0;
const waiting = new Map();
ws.onmessage = (m) => { const d = JSON.parse(m.data); waiting.get(d.id)?.(d); };
const send = (method, params = {}) => new Promise((res) => { waiting.set(++n, res); ws.send(JSON.stringify({ id: n, method, params })); });
const value = async (e) => (await send("Runtime.evaluate", { expression: e, returnByValue: true })).result.result.value;

const targets = {
  strip: `document.querySelector('section[aria-label="Works with"]')`,
  builton: `[...document.querySelectorAll('p')].find((p) => p.querySelector('[data-logo=neatlogs]'))`,
  button: `[...document.querySelectorAll('a')].find((a) => /Install on GitHub/.test(a.textContent))`,
};
for (const width of [1280, 420]) {
  for (const theme of ["light", "dark"]) {
    await send("Emulation.setDeviceMetricsOverride", { width, height: 900, deviceScaleFactor: 2, mobile: false });
    await send("Emulation.setEmulatedMedia", { features: [{ name: "prefers-color-scheme", value: theme }] });
    await send("Page.navigate", { url: base + "/" });
    await sleep(4000);
    for (const [name, sel] of Object.entries(targets)) {
      const r = JSON.parse(await value(`(() => { const e = ${sel}; e.scrollIntoView({block:'center'}); const b = e.getBoundingClientRect(); return JSON.stringify({x: b.x + scrollX, y: b.y + scrollY, w: b.width, h: b.height}); })()`));
      await sleep(900); // let the reveal settle
      const pad = 12;
      const clip = { x: Math.max(0, r.x - pad), y: Math.max(0, r.y - pad), width: Math.min(r.w, width) + pad * 2, height: r.h + pad * 2, scale: 1 };
      const shot = (await send("Page.captureScreenshot", { format: "png", clip, captureBeyondViewport: true })).result.data;
      const f = join(out, `closeup-${name}-${width}-${theme}.png`);
      writeFileSync(f, Buffer.from(shot, "base64"));
      console.log(f);
    }
  }
}
ws.close();
proc.kill();

